"""Contract between the Rust registrations, the binding manifest, the domain modules, the
stubs and the package root.

* ``_binding_manifest.py`` is generated from ``src/api/python`` and from the ``bind_names``
  lists of the domain modules; every registered binding is bound by exactly one module.
* ``_survival.pyi`` is generated by ``scripts/generate_stubs.py``: its name set equals the
  manifest and, for every manifest name, its signatures agree with ``inspect.signature`` of
  the runtime object (``test_stub_signature_matches_runtime``).
* ``__init__.pyi`` mirrors the root export lists of ``__init__.py``; ``r_api.pyi`` tracks the
  public signatures of ``survival.r``.
"""

import ast
import dataclasses
import importlib
import importlib.util
import inspect
import keyword
import re
import runpy
import subprocess
import sys
import tomllib
from pathlib import Path

import pytest

from .helpers import setup_survival_import

ROOT = Path(__file__).resolve().parents[2]
_MANIFEST_SCRIPT = ROOT / "scripts/generate_binding_manifest.py"
_MANIFEST_SPEC = importlib.util.spec_from_file_location(
    "generate_binding_manifest",
    _MANIFEST_SCRIPT,
)
if _MANIFEST_SPEC is None or _MANIFEST_SPEC.loader is None:
    raise RuntimeError(f"Could not load {_MANIFEST_SCRIPT}")
_MANIFEST_MODULE = importlib.util.module_from_spec(_MANIFEST_SPEC)
_MANIFEST_SPEC.loader.exec_module(_MANIFEST_MODULE)

extract_feature_registrations = _MANIFEST_MODULE.extract_feature_registrations
extract_python_module_bindings = _MANIFEST_MODULE.extract_python_module_bindings
extract_rust_registrations = _MANIFEST_MODULE.extract_rust_registrations

PACKAGE_ROOT = ROOT / "python/survival"
STUB_PATH = PACKAGE_ROOT / "_survival.pyi"
README = ROOT / "README.md"
MODULE_METADATA_NAMES = {"__all__", "__version__"}


def _manifest_bindings() -> tuple[str, ...]:
    manifest = runpy.run_path(str(PACKAGE_ROOT / "_binding_manifest.py"))
    return tuple(manifest["BINDINGS"])


def _feature_bindings() -> dict[str, tuple[str, ...]]:
    manifest = runpy.run_path(str(PACKAGE_ROOT / "_binding_manifest.py"))
    return manifest["FEATURE_BINDINGS"]


def _module_bindings() -> dict[str, tuple[str, ...]]:
    manifest = runpy.run_path(str(PACKAGE_ROOT / "_binding_manifest.py"))
    return manifest["MODULE_BINDINGS"]


def _has_ml_bindings(core) -> bool:
    sentinels = ("DeepSurv", "survival_forest", "GradientBoostSurvival")
    return any(hasattr(core, name) for name in sentinels)


def _literal_string_list(node: ast.AST) -> list[str]:
    if not isinstance(node, ast.List | ast.Tuple):
        return []
    return [
        element.value
        for element in node.elts
        if isinstance(element, ast.Constant) and isinstance(element.value, str)
    ]


def _binding_names_by_module() -> dict[str, set[str]]:
    return {module: set(names) for module, names in extract_python_module_bindings(ROOT).items()}


def _root_export_lists() -> dict[str, list[str]]:
    """The three export lists of ``__init__.py`` (the single source of the root surface)."""
    tree = ast.parse((PACKAGE_ROOT / "__init__.py").read_text())
    lists: dict[str, list[str]] = {}
    for node in tree.body:
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if not isinstance(target, ast.Name):
                continue
            if target.id == "_PUBLIC_MODULES" and isinstance(node.value, ast.Dict):
                lists[target.id] = [
                    key.value
                    for key in node.value.keys
                    if isinstance(key, ast.Constant) and isinstance(key.value, str)
                ]
            elif target.id in {"_SKLEARN_EXPORTS", "_R_EXPORTS"}:
                lists[target.id] = _literal_string_list(node.value)
    assert set(lists) == {"_PUBLIC_MODULES", "_SKLEARN_EXPORTS", "_R_EXPORTS"}
    return lists


def _top_level_names() -> set[str]:
    lists = _root_export_lists()
    return (
        set(lists["_PUBLIC_MODULES"])
        | set(lists["_R_EXPORTS"])
        | set(lists["_SKLEARN_EXPORTS"])
        | MODULE_METADATA_NAMES
    )


def _sklearn_names() -> set[str]:
    tree = ast.parse((PACKAGE_ROOT / "sklearn_compat.py").read_text())
    names = {
        node.name
        for node in tree.body
        if isinstance(node, ast.ClassDef | ast.FunctionDef | ast.AsyncFunctionDef)
        and not node.name.startswith("_")
    }
    for node in tree.body:
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id == "_PUBLIC_EXPORTS":
                names.update(_literal_string_list(node.value))
            if isinstance(target, ast.Name) and target.id == "__all__":
                names.update(_literal_string_list(node.value))
    return names


def _remove_survival_modules() -> None:
    for name in tuple(sys.modules):
        if name == "survival" or name.startswith("survival."):
            sys.modules.pop(name, None)


@pytest.fixture(autouse=True)
def _restore_survival_modules():
    """Put back whatever ``survival`` modules were imported before this test.

    Several tests here purge ``survival`` from ``sys.modules`` to watch the package
    import itself lazily.  Re-importing the extension builds fresh type objects, so a
    later test holding a fit made against the old ones fails its ``isinstance`` checks
    (``_is_survreg_fit`` and friends).  Restoring keeps that leakage inside this file.
    """

    saved = {
        name: module
        for name, module in sys.modules.items()
        if name == "survival" or name.startswith("survival.")
    }
    try:
        yield
    finally:
        _remove_survival_modules()
        sys.modules.update(saved)


def _pyi_top_level_names(path: Path) -> set[str]:
    tree = ast.parse(path.read_text(), filename=str(path))
    return {
        node.name
        for node in tree.body
        if isinstance(node, ast.ClassDef | ast.FunctionDef | ast.AsyncFunctionDef)
    }


def _pyi_function_arg_names(path: Path, name: str) -> list[str]:
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == name:
            args = [arg.arg for arg in node.args.posonlyargs]
            args.extend(arg.arg for arg in node.args.args)
            args.extend(arg.arg for arg in node.args.kwonlyargs)
            return args
    raise AssertionError(f"{name} not found in {path}")


def _pyi_function_kwarg_name(path: Path, name: str) -> str | None:
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == name:
            return node.args.kwarg.arg if node.args.kwarg is not None else None
    raise AssertionError(f"{name} not found in {path}")


def _pyi_function_return(path: Path, name: str) -> str:
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == name:
            if node.returns is None:
                return ""
            return ast.unparse(node.returns)
    raise AssertionError(f"{name} not found in {path}")


def _pyi_class_node(path: Path, name: str) -> ast.ClassDef:
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in tree.body:
        if isinstance(node, ast.ClassDef) and node.name == name:
            return node
    raise AssertionError(f"{name} not found in {path}")


def _pyi_class_method_arg_names(path: Path, class_name: str, method_name: str) -> list[str]:
    class_node = _pyi_class_node(path, class_name)
    for node in class_node.body:
        if isinstance(node, ast.FunctionDef) and node.name == method_name:
            args = [arg.arg for arg in node.args.posonlyargs]
            args.extend(arg.arg for arg in node.args.args)
            args.extend(arg.arg for arg in node.args.kwonlyargs)
            return args
    raise AssertionError(f"{class_name}.{method_name} not found in {path}")


def _pyi_class_annotation_names(path: Path, class_name: str) -> set[str]:
    class_node = _pyi_class_node(path, class_name)
    return {
        node.target.id
        for node in class_node.body
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name)
    }


def _readme_python_blocks() -> list[str]:
    return re.findall(r"```python\n(.*?)```", README.read_text(), flags=re.DOTALL)


def _format_missing(missing: list[tuple[str, str]]) -> str:
    return "\n".join(f"{source}: {name}" for source, name in missing)


# ---------------------------------------------------------------------------------------------
# Manifest <-> Rust registrations <-> domain modules
# ---------------------------------------------------------------------------------------------


def test_generated_manifest_matches_rust_registration():
    assert _manifest_bindings() == extract_rust_registrations(ROOT)


def test_generated_feature_manifest_matches_rust_registration():
    assert _feature_bindings() == extract_feature_registrations(ROOT)


def test_generated_module_manifest_matches_python_modules():
    assert _module_bindings() == extract_python_module_bindings(ROOT)


def test_every_registered_binding_is_bound_by_exactly_one_domain_module():
    manifest = set(_manifest_bindings())
    owners: dict[str, list[str]] = {}
    for module, names in _binding_names_by_module().items():
        for name in names:
            owners.setdefault(name, []).append(module)

    unregistered = [
        (f"python/survival/{module}.py", name)
        for name, modules in sorted(owners.items())
        if name not in manifest
        for module in modules
    ]
    unbound = [
        ("python/survival/_binding_manifest.py", name) for name in sorted(manifest - set(owners))
    ]
    duplicated = [
        (", ".join(modules), name) for name, modules in sorted(owners.items()) if len(modules) > 1
    ]

    assert unregistered == [], _format_missing(unregistered)
    assert unbound == [], _format_missing(unbound)
    assert duplicated == [], _format_missing(duplicated)


def _bind_names_literals() -> dict[str, set[str]]:
    """The names each domain module binds straight from the extension (no Python wrapper)."""
    modules: dict[str, set[str]] = {}
    for path in sorted(PACKAGE_ROOT.glob("*.py")):
        if path.name.startswith("_") or path.name in {"__init__.py", "sklearn_compat.py"}:
            continue
        tree = ast.parse(path.read_text(), filename=str(path))
        names: set[str] = set()
        for node in ast.walk(tree):
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "bind_names"
                and len(node.args) >= 2
            ):
                names.update(_literal_string_list(node.args[1]))
        if names:
            modules[path.stem] = names
    return modules


def test_domain_modules_expose_exactly_their_bindings():
    setup_survival_import()
    core = importlib.import_module("survival._survival")
    ml_names = set(_feature_bindings()["ml"]) if not _has_ml_bindings(core) else set()
    direct = _bind_names_literals()
    for module_name, names in _binding_names_by_module().items():
        module = importlib.import_module(f"survival.{module_name}")
        expected = names - ml_names
        assert set(module.__all__) == expected, module_name
        for name in expected:
            if name in direct.get(module_name, set()):
                assert getattr(module, name) is getattr(core, name), f"{module_name}.{name}"
            else:
                assert callable(getattr(module, name)), f"{module_name}.{name}"


