def test_survival_stub_declares_exactly_the_registered_bindings():
    manifest = set(_manifest_bindings())
    stub_names = _pyi_top_level_names(STUB_PATH)

    extra = [("python/survival/_survival.pyi", name) for name in sorted(stub_names - manifest)]
    missing = [
        ("python/survival/_binding_manifest.py", name) for name in sorted(manifest - stub_names)
    ]

    assert extra == [], _format_missing(extra)
    assert missing == [], _format_missing(missing)


def test_survival_stub_is_generated_from_the_extension():
    setup_survival_import()
    core = importlib.import_module("survival._survival")
    if not _has_ml_bindings(core):
        pytest.skip("stub generation needs the extension built with the ml feature")
    result = subprocess.run(  # noqa: S603 - fixed interpreter and script arguments
        [sys.executable, str(ROOT / "scripts/generate_stubs.py"), "--check"],
        capture_output=True,
        text=True,
        check=False,
        cwd=ROOT,
    )
    assert result.returncode == 0, result.stderr[-4000:]


@dataclasses.dataclass(frozen=True)
class _Signature:
    params: tuple[tuple[str, str, object], ...]  # (name, kind, default or NO_DEFAULT)


_NO_DEFAULT = "<no default>"


def _runtime_signature(obj) -> _Signature | None:
    try:
        signature = inspect.signature(obj)
    except (TypeError, ValueError):
        return None
    params = []
    for parameter in signature.parameters.values():
        if parameter.name in {"self", "cls"}:
            continue
        default = _NO_DEFAULT if parameter.default is inspect.Parameter.empty else parameter.default
        params.append((parameter.name, parameter.kind.name, default))
    return _Signature(tuple(params))


def _stub_signature(node: ast.FunctionDef) -> _Signature:
    args = node.args
    params = []
    positional = list(args.posonlyargs) + list(args.args)
    defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
    for index, (arg, default) in enumerate(zip(positional, defaults, strict=True)):
        if arg.arg in {"self", "cls"} and index == 0:
            continue
        kind = "POSITIONAL_ONLY" if arg in args.posonlyargs else "POSITIONAL_OR_KEYWORD"
        params.append((arg.arg, kind, _stub_default(default)))
    if args.vararg is not None:
        params.append((args.vararg.arg, "VAR_POSITIONAL", _NO_DEFAULT))
    for arg, default in zip(args.kwonlyargs, args.kw_defaults, strict=True):
        params.append((arg.arg, "KEYWORD_ONLY", _stub_default(default)))
    if args.kwarg is not None:
        params.append((args.kwarg.arg, "VAR_KEYWORD", _NO_DEFAULT))
    return _Signature(tuple(params))


def _stub_default(node: ast.AST | None):
    if node is None:
        return _NO_DEFAULT
    return ast.literal_eval(node)


def _stub_nodes() -> dict[str, ast.AST]:
    tree = ast.parse(STUB_PATH.read_text(), filename=str(STUB_PATH))
    return {
        node.name: node for node in tree.body if isinstance(node, ast.ClassDef | ast.FunctionDef)
    }


_STUB_NODES = _stub_nodes()
_SKIPPED_DUNDERS = {"__doc__", "__module__", "__new__", "__init__", "__hash__", "__eq__", "__ne__"}
_COMPARISONS = {"__lt__", "__le__", "__gt__", "__ge__"}


@pytest.mark.parametrize("name", sorted(_manifest_bindings()))
def test_stub_signature_matches_runtime(name):
    """Every manifest symbol: the stub's signatures (names, kinds, defaults) equal the runtime's."""
    setup_survival_import()
    core = importlib.import_module("survival._survival")
    if not hasattr(core, name):
        assert name in _feature_bindings()["ml"]
        pytest.skip(f"{name} needs the ml feature")
    runtime = getattr(core, name)
    node = _STUB_NODES[name]

    if not isinstance(runtime, type):
        assert isinstance(node, ast.FunctionDef), f"{name} is a function at runtime"
        assert _stub_signature(node) == _runtime_signature(runtime)
        return

    assert isinstance(node, ast.ClassDef), f"{name} is a class at runtime"
    stub_functions = [n for n in node.body if isinstance(n, ast.FunctionDef)]
    stub_properties = {
        n.name
        for n in stub_functions
        if any(isinstance(d, ast.Name) and d.id == "property" for d in n.decorator_list)
    }
    stub_setters = {
        n.name
        for n in stub_functions
        if any(isinstance(d, ast.Attribute) and d.attr == "setter" for d in n.decorator_list)
    }
    stub_methods = {n.name: n for n in stub_functions if n.name not in stub_properties}
    stub_attributes = {
        n.target.id
        for n in node.body
        if isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name)
    }

    # constructor
    if runtime.__text_signature__ is None:
        assert "__init__" not in stub_methods, f"{name} has no constructor at runtime"
    else:
        assert "__init__" in stub_methods, f"{name} is constructible at runtime"
        assert _stub_signature(stub_methods["__init__"]) == _runtime_signature(runtime)

    # enum variants, properties and methods
    runtime_variants = set()
    runtime_properties = set()
    runtime_methods = {}
    for key, value in runtime.__dict__.items():
        if key in _SKIPPED_DUNDERS or key in _COMPARISONS or keyword.iskeyword(key):
            continue
        if isinstance(value, runtime):
            runtime_variants.add(key)
        elif type(value).__name__ == "getset_descriptor":
            runtime_properties.add(key)
        elif key.startswith("__") and key.endswith("__"):
            continue
        elif type(value).__name__ in {
            "method_descriptor",
            "builtin_function_or_method",
        } or isinstance(value, staticmethod | classmethod):
            runtime_methods[key] = value
    assert stub_attributes == runtime_variants, f"{name}: enum variants"
    assert stub_properties == runtime_properties, f"{name}: properties"
    assert stub_setters <= stub_properties, f"{name}: setters must be properties"
    plain_methods = {k for k in stub_methods if k not in stub_properties and not k.startswith("__")}
    assert plain_methods == set(runtime_methods), f"{name}: methods"
    for method, value in runtime_methods.items():
        stub_node = stub_methods[method]
        decorators = {d.id for d in stub_node.decorator_list if isinstance(d, ast.Name)}
        target = value.__func__ if isinstance(value, staticmethod | classmethod) else value
        if isinstance(value, staticmethod):
            assert "staticmethod" in decorators, f"{name}.{method}"
        elif isinstance(value, classmethod):
            assert "classmethod" in decorators, f"{name}.{method}"
        assert _stub_signature(stub_node) == _runtime_signature(target), f"{name}.{method}"


